package com.pp.shaderlod.optimization.sildurreceiver;import java.util.*;
/** Exact sampler/role support for existing optional receiver quadrature; no all-lit/min/raw contract. */
public final class SildurReceiverContract {private SildurReceiverContract(){}
 public record Sampler(int texture,int width,int height,int format,int bits,int type,int compare,int function,int min,int mag,int base,int wrapS,int wrapT,float bias,float minLod,float maxLod,float aniso){}
 public static boolean role(String name,String half,int[] outputs){return role(name,half,0,outputs);}
 public static boolean role(String name,String half,int spatial,int[] outputs){if(!Set.of("0","1").contains(half)||spatial<0||spatial>2)return false;int light=(half.equals("1")?1:0)+(spatial>0?1:0);return (spatial>0&&name.equals("deferred")&&Arrays.equals(outputs,new int[]{12}))||name.equals(com.pp.shaderlod.optimization.sildurspatial.SildurSpatialContract.stage(light))&&Arrays.equals(outputs,new int[]{4,6});}
 public static boolean worldRole(String name,int[] outputs){return "deferred".equals(name)&&Arrays.equals(outputs,new int[]{14})||"deferred1".equals(name)&&Arrays.equals(outputs,new int[]{4,6});}
 public static boolean worldPixels(int[] v,int w,int h,int outputW,int outputH,float sourceW,float sourceH,boolean producer){return sourceW==w&&sourceH==h&&w==outputW&&h==outputH&&w>=4&&h>=4&&w<=8192&&h<=8192&&Arrays.equals(v,new int[]{0,0,producer?(int)(w*.85f):w,producer?(int)(h*.85f):h});}
 public static boolean sparse(String name,int spatial){return spatial>0&&"deferred".equals(name);}
 public static boolean pixels(int[] v,int w,int h,int outputW,int outputH,float sourceW,float sourceH,boolean sparse,int spatial){return sourceW==w&&sourceH==h&&w==outputW&&h==outputH&&w>0&&h>0&&w<=16384&&h<=16384&&Arrays.equals(v,new int[]{0,0,sparse&&spatial==2?w/2:w,sparse&&spatial==2?h/2:h});}

 private static boolean base(Sampler s,int owner,int resolution){return s!=null&&owner>0&&s.texture()==owner&&resolution==3072&&s.width()==resolution&&s.height()==resolution&&s.base()==0&&s.wrapS()==0x812F&&s.wrapT()==0x812F&&s.bias()==0&&Float.isFinite(s.minLod())&&Float.isFinite(s.maxLod())&&s.minLod()<=0&&s.maxLod()>=0&&s.aniso()==1;}
 public static boolean depth(Sampler s,int owner,int resolution){return base(s,owner,resolution)&&s.compare()==0x884E&&s.function()==0x0203&&s.min()==0x2601&&s.mag()==0x2601&&((s.format()==0x81A5&&s.bits()==16&&s.type()==0x8C17)||(s.format()==0x81A6&&s.bits()==24&&s.type()==0x8C17)||(s.format()==0x81A7&&s.bits()==32&&s.type()==0x8C17)||(s.format()==0x8CAC&&s.bits()==32&&s.type()==0x1406));}
 public static boolean color(Sampler s,int owner,int resolution){return base(s,owner,resolution)&&s.compare()==0&&Set.of(0x2600,0x2601).contains(s.min())&&s.min()==s.mag()&&Set.of(0x8051,0x8054,0x8058,0x805B,0x8814,0x8815,0x881A,0x881B).contains(s.format());}
 public static boolean image(Sampler s,int owner,int w,int h,int format){return s!=null&&owner>0&&s.texture()==owner&&s.width()==w&&s.height()==h&&s.format()==format&&s.base()==0&&s.compare()==0&&Set.of(0x2600,0x2601).contains(s.min())&&s.min()==s.mag()&&s.wrapS()==0x812F&&s.wrapT()==0x812F&&s.bias()==0&&Float.isFinite(s.minLod())&&Float.isFinite(s.maxLod())&&s.minLod()<=0&&s.maxLod()>=0&&s.aniso()==1;}
 public static boolean pixels(int[] v,int w,int h,int outputW,int outputH,float pixelX,float pixelY){return w>0&&h>0&&w<=16384&&h<=16384&&w==outputW&&h==outputH&&Arrays.equals(v,new int[]{0,0,w,h})&&Float.isFinite(pixelX)&&Float.isFinite(pixelY)&&Math.abs(pixelX-1f/w)<=Math.ulp(1f/w)&&Math.abs(pixelY-1f/h)<=Math.ulp(1f/h);}
 public static boolean owner(Object p,Object actualP,Object pack,Object actualPack,Object t,Object actualT,long epoch,long actualEpoch,int id,int actualId){return p!=null&&p==actualP&&pack!=null&&pack==actualPack&&t!=null&&t==actualT&&epoch==actualEpoch&&id>0&&id==actualId;}
}
